<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {collection,documentId,getDocsFromServer,query,where} from 'firebase/firestore'
import {getStagingClients} from '../integrations/firebase/stagingClient'
import {coachBook,type CoachBookingInput} from '../integrations/firebase/coachInbox'
import {bookingPaths,toSlot} from '../integrations/firestore/liveBookings'
import {romeParts,shiftDate,SLOT_MS,type Slot} from '../features/bookings/bookingPolicy'
import type {StagingSession} from '../integrations/firebase/stagingSession'
const props=defineProps<{session:StagingSession;initialDate:string}>()
const emit=defineEmits<{(e:'close'):void;(e:'created',id:string,date:string):void}>()
const today=romeParts(Date.now()).date,maxDate=shiftDate(today,29)
const date=ref(props.initialDate>=today&&props.initialDate<=maxDate?props.initialDate:today)
const athlete=ref(''),athletes=ref<{id:string;name:string}[]>([]),search=ref(''),service=ref<'pesi'|'fighter'>('pesi'),reason=ref('Consegna nuova scheda'),duration=ref<60|120>(60),start=ref<number|null>(null),note=ref(''),slots=ref<Slot[]>([]),loading=ref(false),busy=ref(false),err=ref(''),rosterError=ref('')
const reasons={pesi:['Consegna nuova scheda','Nuova scheda','Consulenza','Aggiornamento scheda','Pesistica','Valutazione','Altro appuntamento'],fighter:['MMA','Boxe','K1','BJJ','Grappling','Karate tradizionale','Karate agonistico','Jiu-jitsu tradizionale','Lezione privata','Altro appuntamento']}
const filtered=computed(()=>athletes.value.filter(x=>x.name.toLocaleLowerCase('it').includes(search.value.toLocaleLowerCase('it'))||x.id===athlete.value))
let alive=true, seq=0, pending:{fingerprint:string;id:string}|null=null
const times=computed(()=>{const open=new Map(slots.value.filter(x=>x.status==='open'&&!x.bookingId).map(x=>[x.startMs,x]));const now=Date.now();return [...open.keys()].filter(t=>romeParts(t).date===date.value&&t>now+15*60000&&t+duration.value*60000<=now+30*86400000&&Array.from({length:duration.value/30},(_,i)=>t+i*SLOT_MS).every(t2=>open.has(t2)&&romeParts(t2).date===date.value)).sort((a,b)=>a-b)})
const who=computed(()=>athletes.value.find(x=>x.id===athlete.value)?.name||'')
const ready=computed(()=>!!who.value&&start.value!==null&&times.value.includes(start.value)&&!loading.value&&!busy.value)
async function loadAthletes(){try{const {db,auth}=getStagingClients();if(auth.currentUser?.uid!==props.session.uid)return;const list=await getDocsFromServer(query(collection(db,'users'),where('gymId','==',props.session.gymId),where('role','==','athlete')));if(alive&&auth.currentUser?.uid===props.session.uid)athletes.value=list.docs.filter(x=>!('membershipStatus' in x.data())||x.data().membershipStatus==='active').map(x=>({id:x.id,name:[x.data().name,x.data().surname].filter(Boolean).join(' ')||'Atleta'})).sort((a,b)=>a.name.localeCompare(b.name,'it'))}catch{if(alive)rosterError.value='Impossibile caricare gli atleti. Riapri la finestra.'}}
async function loadSlots(){const token=++seq;slots.value=[];start.value=null;loading.value=false;if(!/^\d{4}-\d{2}-\d{2}$/.test(date.value)||date.value<today||date.value>maxDate)return;loading.value=true;try{const {db,auth}=getStagingClients(),uid=props.session.uid;if(auth.currentUser?.uid!==uid)return;const day=Date.parse(date.value+'T00:00:00Z');const base=collection(db,'gyms',props.session.gymId,bookingPaths.slots),snap=await getDocsFromServer(query(base,where(documentId(),'>=',uid+'_'+(day-86400000)),where(documentId(),'<',uid+'_'+(day+2*86400000))));if(alive&&token===seq&&auth.currentUser?.uid===uid)slots.value=snap.docs.map(x=>toSlot(x.data())).filter((x):x is Slot=>!!x&&x.coachId===uid)}catch{if(alive&&token===seq)err.value='Slot non aggiornati. Riprova.'}finally{if(alive&&token===seq)loading.value=false}}
watch(date,()=>{err.value='';void loadSlots()});watch(service,()=>{reason.value=reasons[service.value][0]||''});watch(duration,()=>{if(!times.value.includes(start.value??-1))start.value=null});onMounted(()=>{void loadAthletes();void loadSlots()});onUnmounted(()=>{alive=false;seq++})
async function save(){if(!ready.value||start.value===null)return;const d:Omit<CoachBookingInput,'requestId'>={athleteId:athlete.value,service:service.value,discipline:reason.value,startMs:start.value,durationMinutes:duration.value,note:note.value.trim()};if(!window.confirm(`Fissare ${d.discipline} con ${who.value} il ${date.value} alle ${romeParts(d.startMs).time}?`))return;const fingerprint=JSON.stringify(d);if(!pending||pending.fingerprint!==fingerprint)pending={fingerprint,id:crypto.randomUUID()};busy.value=true;err.value='';try{const r=await coachBook(props.session.uid,{...d,requestId:pending.id});if(alive)emit('created',r.id,date.value)}catch(e){if(alive)err.value=e instanceof Error?e.message:'Appuntamento non confermato. Riprova con gli stessi dati.'}finally{if(alive)busy.value=false}}
</script>
<template><section class="panel lf17-coach-form" aria-label="Nuovo appuntamento"><div class="lf17-form-heading"><h2>Nuova prenotazione</h2><button type="button" class="secondary" :disabled="busy" @click="emit('close')">Chiudi</button></div><p class="muted small">Fissa un appuntamento nel tuo calendario con un atleta della palestra. Le fasce devono essere già pubblicate nella sezione Disponibilità.</p><fieldset :disabled="busy"><label>Cerca atleta<input v-model="search" type="search" placeholder="Nome atleta"/></label><label>Atleta<select v-model="athlete"><option value="">Seleziona atleta</option><option v-for="a in filtered" :key="a.id" :value="a.id">{{a.name}}</option></select></label><p v-if="rosterError" role="alert">{{rosterError}}</p><label>Tipologia<select v-model="service"><option value="pesi">Pesistica / schede</option><option value="fighter">Fighter</option></select></label><label>Motivo<select v-model="reason"><option v-for="r in reasons[service]" :key="r">{{r}}</option></select></label><div class="lf17-form-grid"><label>Data<input v-model="date" type="date" :min="today" :max="maxDate"/></label><label>Durata<select v-model.number="duration"><option :value="60">1 ora</option><option :value="120">2 ore</option></select></label></div><label>Orario (Italia)<select v-model="start" :disabled="loading"><option :value="null">{{loading?'Caricamento…':'Seleziona orario'}}</option><option v-for="t in times" :key="t" :value="t">{{romeParts(t).time}} – {{romeParts(t+duration*60000).time}}</option></select></label><p v-if="!loading&&!times.length" class="small muted">Nessuna fascia consecutiva disponibile. Cambia data o pubblica altri slot.</p><label>Messaggio per l’atleta (facoltativo)<textarea v-model="note" maxlength="300" rows="2" placeholder="La tua scheda è pronta!"/></label><p class="small muted">L’appuntamento viene confermato nell’Agenda. L’atleta riceve un avviso interno e, se autorizzata, una push. Google Calendar si aggiorna se collegato.</p></fieldset><button type="button" class="primary wide" :disabled="!ready" @click="save">{{busy?'Salvataggio…':'Conferma appuntamento'}}</button><p v-if="err" role="alert" class="notice">{{err}}</p></section></template>
<style scoped>.lf17-coach-form{display:grid;gap:12px;margin:12px 0}.lf17-form-heading{display:flex;align-items:center;justify-content:space-between;gap:10px}.lf17-form-heading h2{margin:0}.lf17-coach-form fieldset{min-width:0;display:grid;gap:12px;border:0;padding:0;margin:0}.lf17-coach-form label{display:grid;gap:5px;font-weight:600}.lf17-coach-form input,.lf17-coach-form select,.lf17-coach-form textarea{width:100%;min-width:0;box-sizing:border-box}.lf17-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}</style>
